 public GameView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);for(int i=0;i<es.length;i++){es[i]=new Enemy();spawn(es[i]);}}
 void spawn(Enemy e){e.x=rng.nextFloat()*14-7;e.z=10+rng.nextFloat()*17;e.phase=rng.nextFloat()*6.28f;e.alive=true;}
