 void drawHud(Canvas c){rr(c,18,15,255,83,13,0xd918252b);txt(c,"$"+coins+"   ОЧКИ "+score,34,54,20,0xffffdc65);rr(c,270,15,515,83,13,0xd918252b);txt(c,mn[map],287,53,17,Color.WHITE);
  topButton(c,530,15,665,83,"МАГАЗИН");topButton(c,675,15,790,83,"КАРТЫ");topButton(c,800,15,925,83,"МЕНЮ");topButton(c,935,15,1055,83,aiming?"ПРИЦЕЛ ✓":"ПРИЦЕЛ");topButton(c,1065,15,1175,83,"ЗАРЯД");rr(c,1182,15,1262,83,13,0xd918252b);txt(c,"$"+ammo,1194,54,18,Color.WHITE);
  txt(c,wn[weapon],930,111,17,0xffffffff);if(aiming){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(0x77ffffff);c.drawCircle(640,350,75,p);p.setStyle(Paint.Style.FILL);}
  float gap=aiming?13:20;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(Color.WHITE);c.drawCircle(640,350,gap,p);c.drawLine(600,350,640-gap-8,350,p);c.drawLine(640+gap+8,350,680,350,p);c.drawLine(640,310,640,350-gap-8,p);c.drawLine(640,350+gap+8,640,390,p);p.setStyle(Paint.Style.FILL);circ(c,640,350,3,Color.RED);
  circ(c,120,585,74,0x55202930);circ(c,120+jx*36,585-jy*36,31,0xbbf1f3f4);txt(c,"ДВИЖЕНИЕ",68,687,15,Color.WHITE);circ(c,1140,565,72,0xffcf4837);txt(c,weapon==4?"УДАР":"ОГОНЬ",1097,574,22,Color.WHITE);}
 void topButton(Canvas c,int l,int t,int r,int b,String s){rr(c,l,t,r,b,13,0xe027343a);txt(c,s,l+10,(t+b)/2f+7,16,Color.WHITE);}
 void shoot(long now){lastShot=now;if(weapon!=4&&ammo<=0){say("Нет патронов — нажми ЗАРЯД");firing=false;return;}if(weapon!=4)ammo-=weapon==2?Math.min(2,ammo):1;Enemy best=null;float near=Float.MAX_VALUE;for(Enemy e:es)if(e.alive){float[] foot=project(e.x,0,e.z),head=project(e.x,1.95f,e.z),center=project(e.x,1.08f,e.z);if(foot==null||head==null||center==null)continue;float h=foot[1]-head[1],w=h*.50f,rx=w*.39f,ry=h*.19f;float nx=(640-center[0])/Math.max(1,rx),ny=(350-center[1])/Math.max(1,ry);float d=(float)Math.hypot(e.x-px,e.z-pz);float range=weapon==4?2.5f:weapon==3?48:36;if(nx*nx+ny*ny<=1&&d<=range&&d<near){near=d;best=e;}}if(best!=null){best.alive=false;score++;coins+=10;say("ПОПАДАНИЕ  +10 монет");spawn(best);}else say(weapon==4?"Подойди ближе к цели":"Мимо — наведи круг на жёлтый хитбокс");}
 int maxAmmo(){return weapon==0?12:weapon==1?30:weapon==2?8:weapon==3?5:0;}void start(){screen=3;px=pz=yaw=pitch=0;aiming=false;ammo=maxAmmo();for(Enemy e:es)spawn(e);}
