 void drawMenu(Canvas c){bg(c,0xff263b49);txt(c,"POULTRY STRIKE",350,150,58,Color.WHITE);txt(c,"ARENA SHOOTER",495,200,22,0xffffd15d);button(c,420,245,860,325,"ИГРАТЬ",0xffcf4837,32);button(c,420,345,860,425,"МАГАЗИН",0xff347659,27);button(c,420,445,860,525,"ВЫБРАТЬ КАРТУ",0xff485b6d,24);txt(c,"Монеты: $"+coins+"   •   Свайп — поворот камеры",410,610,20,Color.WHITE);}
 void drawShop(Canvas c){bg(c,0xff29373e);txt(c,"МАГАЗИН ОРУЖИЯ   $"+coins,350,76,35,Color.WHITE);button(c,20,12,185,76,"НАЗАД",0xff52616a,19);for(int i=0;i<5;i++){int x=35+i*245;rr(c,x,130,x+220,545,17,weapon==i?0xff42624f:0xff3a4a52);txt(c,wn[i],x+12,176,16,Color.WHITE);rr(c,x+47,225,x+173,300,11,0xff242d32);if(i==4){poly(c,new float[][]{{x+98,292},{x+123,296},{x+154,225},{x+141,218}},0xffc5d2d8);}else rr(c,x+64,244,x+157,281,8,0xff78868b);txt(c,owned[i]?(weapon==i?"ЭКИПИРОВАНО":"КУПЛЕНО"):"ЦЕНА $"+cost[i],x+25,390,16,0xffffdc65);button(c,x+18,430,x+202,494,owned[i]?"ВЫБРАТЬ":"КУПИТЬ",owned[i]?0xff38875a:0xffbb7139,18);}txt(c,"Монеты за попадания: +10",472,612,19,Color.WHITE);}
 void drawMaps(Canvas c){bg(c,0xff293b49);txt(c,"ВЫБОР КАРТЫ",435,76,40,Color.WHITE);button(c,20,12,185,76,"НАЗАД",0xff52616a,19);for(int i=0;i<3;i++){int x=90+i*375;rr(c,x,150,x+335,490,17,i==map?0xff41624f:0xff465258);int col=i==1?0xffe4b16f:i==2?0xffaed2e1:0xff69b4da;rect(c,x+12,162,x+323,355,col);rect(c,x+12,355,x+323,478,i==1?0xffb99163:i==2?0xffcad9df:0xff938b70);txt(c,mn[i],x+30,425,21,Color.WHITE);button(c,x+40,505,x+295,565,i==map?"ВЫБРАНА":"ВЫБРАТЬ",0xff34865b,19);}button(c,470,615,810,685,"НАЧАТЬ ИГРУ",0xffcf4837,22);}
 boolean inside(float x,float y,int l,int t,int r,int b){return x>=l&&x<=r&&y>=t&&y<=b;}void joy(float x,float y){float a=(x-120)/68f,b=(585-y)/68f,d=(float)Math.hypot(a,b);if(d>1){a/=d;b/=d;}jx=a;jy=b;}
 @Override public boolean onTouchEvent(MotionEvent e){int act=e.getActionMasked(),ix=e.getActionIndex(),id=e.getPointerId(ix);float x=e.getX(ix)*1280/getWidth(),y=e.getY(ix)*720/getHeight();if(act==MotionEvent.ACTION_DOWN||act==MotionEvent.ACTION_POINTER_DOWN){if(screen==0){if(inside(x,y,420,245,860,325))start();else if(inside(x,y,420,345,860,425))screen=1;else if(inside(x,y,420,445,860,525))screen=2;return true;}if(screen==1){if(inside(x,y,20,12,185,76)){screen=0;return true;}for(int k=0;k<5;k++){int bx=35+k*245;if(inside(x,y,bx,130,bx+220,545)){if(owned[k]){weapon=k;ammo=maxAmmo();say("Выбрано: "+wn[k]);}else if(coins>=cost[k]){coins-=cost[k];owned[k]=true;weapon=k;ammo=maxAmmo();say("Куплено: "+wn[k]);}else say("Не хватает монет");return true;}}return true;}if(screen==2){if(inside(x,y,20,12,185,76)){screen=0;return true;}for(int k=0;k<3;k++){int bx=90+k*375;if(inside(x,y,bx,150,bx+335,570))map=k;}if(inside(x,y,470,615,810,685))start();return true;}
   if(x<240&&y>455&&y<625){joyId=id;joy(x,y);return true;}if(y<100){if(x>=530&&x<670){screen=1;return true;}if(x>=675&&x<795){screen=2;return true;}if(x>=800&&x<930){screen=0;return true;}if(x>=935&&x<1060){aiming=!aiming;return true;}if(x>=1065&&x<1180){ammo=maxAmmo();say("Перезаряжено");return true;}}
   if(x>1050&&y>465&&y<640){fireId=id;firing=true;shoot(System.currentTimeMillis());return true;}lookId=id;lastX=x;lastY=y;return true;}
  if(act==MotionEvent.ACTION_MOVE){for(int k=0;k<e.getPointerCount();k++){int pid=e.getPointerId(k);float tx=e.getX(k)*1280/getWidth(),ty=e.getY(k)*720/getHeight();if(pid==joyId)joy(tx,ty);if(pid==lookId){float dx=tx-lastX,dy=ty-lastY;/* drag right looks right; drag up looks up */yaw+=dx*.006f;pitch=Math.max(-.65f,Math.min(.65f,pitch-dy*.005f));lastX=tx;lastY=ty;}}return true;}
  if(act==MotionEvent.ACTION_UP||act==MotionEvent.ACTION_POINTER_UP||act==MotionEvent.ACTION_CANCEL){if(id==joyId){joyId=-1;jx=jy=0;}if(id==lookId)lookId=-1;if(id==fireId){fireId=-1;firing=false;}if(act==MotionEvent.ACTION_CANCEL){joyId=lookId=fireId=-1;jx=jy=0;firing=false;}return true;}return true;}
